<?php
require_once __DIR__.'/../includes/bootstrap.php'; require_admin();
$from = $_GET['from'] ?? date('Y-m-d'); $to = $_GET['to'] ?? date('Y-m-d'); $uid=(int)($_GET['user_id']??0); $action=trim((string)($_GET['action']??'')); $search=trim((string)($_GET['q']??''));
$where=['DATE(a.created_at) BETWEEN ? AND ?']; $params=[$from,$to];
if($uid>0){$where[]='a.user_id=?';$params[]=$uid;} if($action!==''){$where[]='a.action=?';$params[]=$action;} if($search!==''){$where[]='(a.details LIKE ? OR a.user_name LIKE ? OR a.action LIKE ?)';$like='%'.$search.'%';array_push($params,$like,$like,$like);}
$sql='SELECT a.* FROM activity_logs a WHERE '.implode(' AND ',$where).' ORDER BY a.id DESC LIMIT 500'; $st=db()->prepare($sql);$st->execute($params);$rows=$st->fetchAll();
$users=db()->query('SELECT id,name FROM users ORDER BY name')->fetchAll();$actions=db()->query('SELECT DISTINCT action FROM activity_logs ORDER BY action')->fetchAll(PDO::FETCH_COLUMN);
$counts=['total'=>count($rows),'user'=>0,'sales'=>0,'stock'=>0,'system'=>0];foreach($rows as $r){if(isset($counts[$r['category']]))$counts[$r['category']]++;}
$pageTitle='Activity Log';$pageSubtitle='Track all important actions in your POS system';include __DIR__.'/../includes/header.php';
?>
<style>
.activity-page{padding-bottom:70px}.activity-filter{display:grid;grid-template-columns:1fr 1fr 1.2fr 1.4fr 1.6fr auto auto;gap:10px;align-items:end}.activity-filter label{font-size:12px;font-weight:800;color:#40584f}.activity-filter input,.activity-filter select{width:100%;margin-top:5px;height:42px;border:1px solid #d5e3dd;border-radius:9px;padding:0 11px;background:#fff}.activity-cards{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:16px 0}.activity-cards article{border:1px solid #dce8e3;border-radius:14px;padding:16px;background:#fff}.activity-cards small{display:block;color:#64776f;font-weight:700}.activity-cards strong{display:block;margin-top:6px;font-size:24px;color:#12392b}.activity-table-wrap{overflow:auto;max-height:560px}.activity-table{width:100%;border-collapse:collapse}.activity-table th{position:sticky;top:0;background:#f5faf7;z-index:2}.activity-table th,.activity-table td{padding:11px 12px;border-bottom:1px solid #e3ebe7;text-align:left;font-size:13px;vertical-align:top}.role-pill,.action-pill{display:inline-flex;padding:5px 9px;border-radius:999px;font-size:11px;font-weight:800}.role-pill.admin{background:#ffe6e6;color:#c62828}.role-pill.cashier{background:#ddf8e9;color:#087a4d}.action-pill{background:#eef4ff;color:#225fbd}.cat-sales{background:#fff1e5;color:#d45a00}.cat-stock{background:#f0e8ff;color:#6d3ac8}.cat-system{background:#ffeaf4;color:#bf276b}.cat-user{background:#e7f2ff;color:#1569b7}@media(max-width:1100px){.activity-filter{grid-template-columns:repeat(2,1fr)}.activity-cards{grid-template-columns:repeat(2,1fr)}}
</style>
<section class="activity-page">
<section class="panel"><h2 style="margin-top:0">Activity Log</h2><p style="color:#718078">View all user actions and system activities. View only.</p><form class="activity-filter" method="get"><label>Date From<input type="date" name="from" value="<?=e($from)?>"></label><label>Date To<input type="date" name="to" value="<?=e($to)?>"></label><label>User<select name="user_id"><option value="0">All Users</option><?php foreach($users as $u):?><option value="<?=e($u['id'])?>" <?=$uid===(int)$u['id']?'selected':''?>><?=e($u['name'])?></option><?php endforeach;?></select></label><label>Action Type<select name="action"><option value="">All Actions</option><?php foreach($actions as $a):?><option <?=$action===$a?'selected':''?>><?=e($a)?></option><?php endforeach;?></select></label><label>Search<input name="q" value="<?=e($search)?>" placeholder="Search details..."></label><button class="btn primary">Filter</button><a class="btn" href="activity_log.php">Reset</a></form></section>
<div class="activity-cards"><article><small>Total Activities</small><strong><?=e($counts['total'])?></strong></article><article><small>User Management</small><strong><?=e($counts['user'])?></strong></article><article><small>Sales Actions</small><strong><?=e($counts['sales'])?></strong></article><article><small>Stock Adjustments</small><strong><?=e($counts['stock'])?></strong></article><article><small>System Actions</small><strong><?=e($counts['system'])?></strong></article></div>
<section class="panel"><div class="activity-table-wrap"><table class="activity-table"><thead><tr><th>#</th><th>Date & Time</th><th>User</th><th>Role</th><th>Action</th><th>Details</th></tr></thead><tbody><?php foreach($rows as $i=>$r):?><tr><td><?=e(count($rows)-$i)?></td><td><?=date('d M Y, h:i A',strtotime($r['created_at']))?></td><td><?=e($r['user_name'])?></td><td><span class="role-pill <?=e($r['user_role'])?>"><?=e(ucfirst($r['user_role']))?></span></td><td><span class="action-pill cat-<?=e($r['category'])?>"><?=e($r['action'])?></span></td><td><?=e($r['details']?:'—')?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" style="text-align:center;padding:30px;color:#718078">No activity found for this filter.</td></tr><?php endif;?></tbody></table></div></section>
</section>
<?php require __DIR__.'/../includes/footer.php'; ?>